using System;using System.Linq;using System.Collections.Generic;using System.Text.Json;using MotorwaysSim;
class Checkpoints{static void Main(string[] args){var json=new JsonSerializerOptions{IncludeFields=true,PropertyNameCaseInsensitive=true};var d=JsonSerializer.Deserialize<CustomScenarioDefinition>(System.IO.File.ReadAllText(args[0]),json);using var refs=JsonDocument.Parse(System.IO.File.ReadAllText(args[1]));var session=new CustomScenarioSession(d);var result=new List<object>();var wall=System.Diagnostics.Stopwatch.StartNew();foreach(var checkpoint in refs.RootElement.EnumerateArray()){double at=checkpoint.GetProperty("at").GetDouble();while(session.World.Time+1e-8<at&&!session.Complete){if(wall.Elapsed.TotalSeconds>30)throw new Exception("Checkpoint diagnostic30-second wall limit");session.AdvanceTick();}var w=session.World;var edges=new List<int[]>();var nodes=new List<int[]>();for(int y=0;y<TrafficWorld.Height;y++)for(int x=0;x<TrafficWorld.Width;x++){var a=new Cell(x,y);if(w.Tile(a)==Infrastructure.Road)nodes.Add(new[]{x,y});for(int dir=0;dir<8;dir++)if((w.Connections[x,y]&(1<<dir))!=0){var b=a+TrafficWorld.Directions[dir];if(a.CompareTo(b)<0)edges.Add(new[]{x,y,b.X,b.Y});}}result.Add(new{video=checkpoint.GetProperty("video").GetDouble(),w.Time,roadStock=w.Inventory[0],edges,roadNodes=nodes,houseDirections=w.Buildings.Where(b=>b.IsHouse).Select(b=>new[]{b.Cell.X,b.Cell.Y,b.DrivewayDirection}).ToArray(),w.Failed,events=session.CompletedEvents});}Console.WriteLine(JsonSerializer.Serialize(result,json));}}
